//! Maya command equivalent of each MCP tool, rendered as a column of
//! `.project-docs/mcp-tools.md` by `registry::tests::tool_doc_matches_registry`.
//!
//! Sources: Maya 2027 Python command reference, `https://help.autodesk.com/cloudhelp/2027/ENU/Maya-Tech-Docs/CommandsPython/<command>.html`
//! (summarised, never copied). PROVISIONAL marks a mapping checked only at page-existence level or
//! approximated; "no equivalent" means no Maya command does this.

/// `(tool, Maya equivalent, documented difference)`, in registry order.
#[rustfmt::skip]
pub(crate) const MAYA_MAP: &[(&str, &str, &str)] = &[
    ("inspect_scene", "`ls`, `listRelatives`, `getAttr`, `xform -q`, `polyEvaluate`, `currentUnit -q`, `camera -q`", "one paged snapshot instead of per-command queries"),
    ("set_active_tool", "`setToolTo`", "Select, Move, Rotate and Scale only"),
    ("set_tool_space", "`manipRotateContext` / `manipScaleContext -mode`", "object and world only; Move not covered (PROVISIONAL)"),
    ("set_tool_handle", "`-currentActiveHandle` on the manip contexts", "none known (PROVISIONAL)"),
    ("set_manipulator_size", "`manipOptions -scale`", "values rounded to three decimals (AztecCraft rule)"),
    ("begin_manipulation", "`move` / `rotate` / `scale` inside `undoInfo -openChunk`", "no Maya single-call equivalent of a remote-owned preview (PROVISIONAL)"),
    ("update_manipulation", "`move` / `rotate` / `scale -absolute`", "absolute value only; no one-call relative transform"),
    ("finish_manipulation", "`undoInfo -closeChunk` (commit); `undo` (cancel)", "cancel restores the begin state exactly (PROVISIONAL)"),
    ("create_primitive", "`polyCube`, `polyPlane`, `polySphere`, `polyCylinder`, `polyCone`, `polyTorus`", "Maya returns transform and history node names and creates UVs and history by default"),
    ("select_node", "`select -replace`", "no `-addFirst`; no components in the same call"),
    ("modify_selection", "`select -add` / `-deselect` / `-toggle`", "operates on one instance per call"),
    ("select_by_rule", "`select -all` / `-hierarchy`; inverse via `ls` plus `select`", "inverse has no single Maya flag (PROVISIONAL)"),
    ("select_in_rect", "`select -replace` with a marquee; no scripted equivalent", "Maya marquee selection is a UI drag, not a command (PROVISIONAL)"),
    ("deselect_all", "`select -clear`", "also returns to Object selection mode"),
    ("set_selection_mode", "`selectMode`, `selectType`", "exclusive component modes"),
    ("select_face", "`select pCube1.f[n]`", "one component, no ranges"),
    ("select_vertex", "`select pCube1.vtx[n]`", "one component, no ranges"),
    ("select_edge", "`select pCube1.e[n]`", "one component, no ranges"),
    ("rename_node", "`rename`", "refuses a name conflict instead of making a unique name; no `:` namespaces; shape names always follow"),
    ("set_transform", "`xform -translation -rotation -scale`, `setAttr`", "rotation in degrees regardless of `currentUnit -angle`"),
    ("edit_node", "`xform`, `setAttr`, `rename`", "one undo entry; rotation in degrees regardless of `currentUnit -angle`"),
    ("extrude_face", "`polyExtrudeFacet -localTranslateZ`", "one quad, no history node"),
    ("create_joint", "`joint -position -relative -radius -name`", "session-only, not saved; joint chains only, no orientation, rotation 0 and scale 1 (PROVISIONAL)"),
    ("set_current_time", "`currentTime`", "whole frames only"),
    ("set_keyframe", "`setKeyframe`", "linear interpolation, no tangents (PROVISIONAL); transform channels only"),
    ("delete_keys", "`cutKey -clear`", "transform channels only"),
    ("set_playback_range", "`playbackOptions -min -max`", "whole frames; animation range not separate (PROVISIONAL)"),
    ("play_timeline", "`play -forward true`", "fixed 24 fps looping; no `-wait`"),
    ("stop_timeline", "`play -state off` (PROVISIONAL: flag semantics unconfirmed beyond the synopsis)", "none known (PROVISIONAL)"),
    ("inspect_keys", "`keyframe -q`", "paged table of stored keys"),
    ("project_uv_planar", "`polyPlanarProjection`", "fitted to the shape bounds on a chosen axis; session-only, not saved"),
    ("delete_uvs", "`polyMapDel`", "removes the whole session-only map1 and takes no face selection; `polyMapDel` deletes the UVs of the selected faces"),
    ("inspect_uvs", "`polyEvaluate -uvcoord`, `polyEditUV -q`", "paged per-corner list, f32"),
    ("set_material_diffuse", "`setAttr <shader>.diffuse`", "none known"),
    ("create_session_material", "`shadingNode -asShader lambert`", "session-only, not saved"),
    ("assign_session_material", "`sets -renderable true -noSurfaceShader true -empty`, `sets -forceElement`", "session-only, not saved; whole shape"),
    ("set_session_material_color", "`setAttr <shader>.color`", "session-only, not saved"),
    ("delete_node", "`delete`", "refuses hierarchies and shared descendants (#187)"),
    ("delete_selected", "`delete` with no flags", "all or nothing"),
    ("undo", "`undo`", "closes an open undo chunk first; the chunk is then the step reverted if it changed the scene"),
    ("redo", "`redo`", "closes an open undo chunk first"),
    ("set_undo_queue", "`undoInfo -infinity`, `-length`", "session-only, not a persisted preference (#178); Finite size 1 to 1000; a smaller size drops the oldest steps at once (PROVISIONAL)"),
    ("set_undo_enabled", "`undoInfo -state`, `-stateWithoutFlush`", "an edit made while undo is off flushes both queues (stricter than Maya); flush defaults to true when turning off, false when turning on (PROVISIONAL); Undo and Redo while off report unchanged, read undo_state.enabled"),
    ("open_undo_chunk", "`undoInfo -openChunk -chunkName`", "chunks do not nest; an unnamed chunk is called Chunk (PROVISIONAL)"),
    ("close_undo_chunk", "`undoInfo -closeChunk`", "a chunk with no net change records no step"),
    ("frame_selected", "`viewFit`", "no `-fitFactor` or `-animate`"),
    ("frame_all", "`viewFit -allObjects`", "no `-fitFactor` or `-animate`"),
    ("set_grid_visibility", "`grid -toggle`, `modelEditor -grid`", "current viewport only"),
    ("set_shading_mode", "`modelEditor -displayAppearance wireframe` / `smoothShaded`", "two modes"),
    ("orbit_camera", "`tumble`", "radians; pitch clamps near the poles"),
    ("set_camera_pose", "`viewPlace -eyePoint` (PROVISIONAL: flag semantics unconfirmed beyond the synopsis), `camera -e`", "target, distance, yaw and pitch; FOV and clip planes untouched (PROVISIONAL)"),
    ("pan_camera", "`track`", "camera-plane world units"),
    ("dolly_camera", "`dolly`", "multiplicative factor"),
    ("set_menu_set", "`setMenuMode`", "Modeling and Rigging only; session-only (PROVISIONAL)"),
    ("set_sidebar_panel_visibility", "`workspaceControl -e -visible`", "fixed dock; the 2027 attribute editor page was not found (PROVISIONAL)"),
    ("select_attribute_editor_tab", "no equivalent", "Maya has no command for choosing an Attribute Editor tab (PROVISIONAL)"),
    ("open_scene", "`file -open`", "dirty confirmation is a separate `resolve_file_action` step; Maya uses `-force`"),
    ("save_scene", "`file -save`", "Maya binary only"),
    ("save_scene_as", "`file -rename`, then `file -save -type`", "never overwrites"),
    ("export_obj", "`file -exportAll` / `-exportSelected -type \"OBJexport\"`", "faces only, centimeters, never overwrites (PROVISIONAL: OBJexport options)"),
    ("new_scene", "`file -new`", "dirty confirmation via `resolve_file_action`; Maya uses `-force`"),
    ("resolve_file_action", "no equivalent", "Maya prompts in a dialog or takes `-force`"),
    ("request_close", "`quit`", "dirty confirmation required"),
];
